714:         research_o.did = req_data.did;
715:         research_o.normal = e3_normal;
716:         research_o.lookup = e3_normal && state_q == PT && !e3_seen_q;
717:         research_o.hit = iotlb_lu_hit;
718:         research_o.iova = 64'(req_data.iova);
719:         research_o.pscid = iotlb_lu_pscid;
720:         research_o.gscid = iotlb_lu_gscid;
721:         research_o.stage1 = en_1S_q;
722:         research_o.stage2 = en_2S_q;
723:     end
